#!/usr/bin/env python3
import subprocess
import sys

def read_passwd():
    try:
        with open('/etc/passwd', 'r') as f:
            content = f.read()
        return content
    except Exception as e:
        return f"Error reading /etc/passwd: {e}"

if __name__ == '__main__':
    result = read_passwd()
    print(result)

