#!/usr/bin/env python3
"""Script to read /etc/passwd and output its contents."""

def read_passwd():
    try:
        with open('/etc/passwd', 'r') as f:
            content = f.read()
        return content
    except Exception as e:
        return f"Error reading /etc/passwd: {e}"

if __name__ == '__main__':
    output = read_passwd()
    print(output)
